SysDataModelXML.SQLScript:
DECLARE @SITE NVARCHAR(30) = N'{0}'; DECLARE @DOCNUM NVARCHAR(30) = N'%{1}%'; DECLARE @ITMDES NVARCHAR(300) = N'%{2}%'; DECLARE @DATSTR DATE = '{3}'; DECLARE @DATEND DATE = '{4}'; DECLARE @DEPT NVARCHAR(30) = '{5}';
WITH BaseData AS ( -- 先获取核心数据，减少连接次数 SELECT TOP 500 S.ID AS LINKROWID, S.DOCNUM, S.DOCLIN, S.ITMNO, S.ITMVER, S.REQDAT, S.UOM, S.UOMCOE, S.QTY, S.STU, S.QTYSTU, S.REMARK AS LREMARK, S.SRCTYP, S.SRCDOC, S.SRCLIN, S.CLOREA AS LCLOREA, S.PINNUM, S.PFBTIM, S.CREUSR, S.UPDUSR, S.CRETIM, S.UPDTIM, ITM.ITMNOORI, ITM.ITMNAM, ITM.ITMNAM1, ITM.ITMNAM2, ITM.TSICOD1, ITM.TSICOD2, ITM.TSICOD3, ITM.TSICOD4, ITM.TSICOD5, ITM.ITMSIZE, ITM.ITMSPEC, H.DOCGRP, H.DOCDES, H.PRJNUM, H.SITE, H.DEPT, H.GRP, H.RESNO, H.REMARK, H.DOCDAT, S.DOCTYP, S.DOCSTA FROM PREQUL S INNER JOIN ITM ON ITM.ITMNO = S.ITMNO INNER JOIN PREQUH H ON S.DOCNUM = H.DOCNUM WHERE H.SITE = @SITE AND (@DOCNUM = '%' OR S.DOCNUM LIKE @DOCNUM) AND (@ITMDES = '%' OR (S.ITMNO + S.ITMVER + ITM.ITMNAM + ITM.ITMNAM1) LIKE @ITMDES) AND H.DOCDAT BETWEEN @DATSTR AND @DATEND AND (@DEPT = '' OR H.DEPT = @DEPT) ORDER BY S.DOCNUM DESC, S.DOCLIN ), OrderInfo AS ( -- 订单信息单独处理 SELECT COALESCE(D1.SRCDOC, D2.SRCDOC) AS SRCDOC, COALESCE(D1.SRCLIN, D2.SRCLIN) AS SRCLIN, COALESCE(D1.DOCNUM, D2.DOCNUM) AS PORDOCNUM, COALESCE(D1.DOCLIN, D2.DOCLIN) AS PORLIN, CASE WHEN D1.DOCNUM IS NOT NULL THEN '询价订单' WHEN D2.DOCNUM IS NOT NULL THEN '直接订单' ELSE '无订单' END AS ORDERTYPE, PR.CREUSR AS PORCREUSR, PR.WFLTIM AS PORWFLTIM, PR.DOCNUM AS ORDERDOCNUM, S.DOCNUM, S.DOCLIN FROM PREQUL S LEFT JOIN PINQUL PL ON PL.DOCNUM = S.PINNUM AND PL.ITMNO = S.ITMNO LEFT JOIN PORDLIN D1 ON PL.DOCNUM = D1.SRCDOC AND PL.DOCLIN = D1.SRCLIN AND D1.SRCTYP = 'PIN' AND NOT (D1.DOCSTA = '4' AND D1.CLOREA <> '') AND ( D1.DOCSTA <> '4' OR ISNULL(D1.CLOREA, '') = '' ) LEFT JOIN PORDLIN D2 ON S.DOCNUM = D2.SRCDOC AND S.DOCLIN = D2.SRCLIN AND D2.SRCTYP = 'PRQ' LEFT JOIN PORDER PR ON COALESCE(D1.DOCNUM, D2.DOCNUM) = PR.DOCNUM WHERE S.DOCSTA = 2 --AND S.PCKTIM IS NULL ), ShippingInfo AS ( -- 物流信息单独处理 SELECT SRCDOC, SRCLIN, MIN(DOCNUM) AS PBHNUM FROM PBOLD WHERE SRCTYP = 'POR' GROUP BY SRCDOC, SRCLIN ), ReceiveInfo AS ( -- 收货信息单独处理 SELECT SRCDOC, SRCLIN, MIN(DOCNUM) AS PRCDOC, MIN(SUBTIM) AS PRCDAT FROM PRECLIN WHERE SRCTYP = 'POR' GROUP BY SRCDOC, SRCLIN )
SELECT BD.LINKROWID, BD.DOCNUM, BD.DOCLIN, BD.ITMNO, BD.ITMNOORI, BD.ITMNAM, BD.ITMNAM1, BD.ITMNAM2, BD.ITMVER, BD.TSICOD1, BD.TSICOD2, BD.TSICOD3, BD.TSICOD4, BD.TSICOD5, BD.ITMSIZE, BD.ITMSPEC, CONVERT(VARCHAR, BD.REQDAT, 23) AS REQDAT, BD.UOM, CAST(BD.UOMCOE AS REAL) AS UOMCOE, CAST(BD.QTY AS REAL) AS QTY, BD.STU, CAST(BD.QTYSTU AS REAL) AS QTYSTU, BD.LREMARK, BD.SRCTYP, BD.SRCDOC, BD.SRCLIN, DOCSTA.OPTDES AS DOCSTA, BD.LCLOREA, BD.DOCGRP, DOCGRP.OPTDES AS DOCGRPDES, BD.DOCDES, BD.PRJNUM, BD.SITE, SI.SITENAM AS SITEDES, BD.DEPT, D.DEPTNAM AS DEPTDES, BD.GRP, G.GRPNAM AS GRPDES, BD.RESNO, R.RESNAM AS RESNODES, BD.REMARK, CONVERT(VARCHAR(16), BD.PFBTIM, 21) AS PFBTIM, CONVERT(VARCHAR(16), OI.PORWFLTIM, 21) AS WFLTIM, IIF(DATEDIFF(DAY, BD.PFBTIM, ISNULL(OI.PORWFLTIM, GETDATE())) > 15, 'D04', '') AS LINKAPPRROW, BD.CREUSR, BD.UPDUSR, CONVERT(VARCHAR(16), BD.CRETIM, 21) AS CRETIM, CONVERT(VARCHAR(16), BD.UPDTIM, 21) AS UPDTIM, -- PINNUM逻辑优化 CASE WHEN (BD.PINNUM IS NULL OR BD.PINNUM = '') AND OI.ORDERDOCNUM IS NULL THEN '未询价' WHEN BD.PINNUM IS NULL AND OI.ORDERDOCNUM IS NOT NULL THEN '直接生成订单' ELSE BD.PINNUM END AS PINNUM, CONVERT(VARCHAR(10), PH.DOCDAT, 21) AS PINDAT, -- PORNUM逻辑优化 CASE WHEN OI.ORDERDOCNUM IS NULL THEN '未采购' ELSE OI.ORDERDOCNUM END AS PORNUM, LINK.DBO.GetUserNameByCode(OI.PORCREUSR) AS PORCREUSR, CONVERT(VARCHAR(16), OI.PORWFLTIM, 23) AS PORDAT, DATEDIFF(DAY, ISNULL(BD.PFBTIM, GETDATE()), ISNULL(OI.PORWFLTIM, GETDATE())) AS PURDAT, -- 物流信息 PBH.DOCNUM AS PBHNUM, CONVERT(VARCHAR(10), PBH.DOCDAT, 21) AS PBHDAT, CONVERT(VARCHAR(10), PBH.ETD, 21) AS ETD, CONVERT(VARCHAR(10), PBH.ETA, 21) AS ETA, CONVERT(VARCHAR(10), PBH.BLD, 21) AS BLD, -- 收货信息 RI.PRCDOC, CONVERT(VARCHAR(10), RI.PRCDAT, 21) AS PRCDAT, -- 超期标记 CASE WHEN DATEDIFF(DAY, ISNULL(BD.PFBTIM, GETDATE()), ISNULL(OI.PORWFLTIM, GETDATE())) > 15 THEN 'G04' ELSE '' END AS LINKAPPRPURDAT FROM BaseData BD LEFT JOIN LINKOPT DOCSTA ON DOCSTA.OPTID =BD.DOCSTA AND DOCSTA.OPTTYP = 'DOCSTA' LEFT JOIN ENTSITE SI ON BD.SITE = SI.SITE LEFT JOIN LINKOPT DOCGRP ON BD.DOCGRP = DOCGRP.OPTID AND DOCGRP.OPTTYP = 'DOCGRP' AND DOCGRP.LINKOPTID = 'PRE' LEFT JOIN ENTDEPT D ON BD.DEPT = D.DEPT LEFT JOIN ENTGRP G ON BD.GRP = G.GRP LEFT JOIN ENTRES R ON BD.RESNO = R.RESNO LEFT JOIN PINQUH PH ON PH.DOCNUM = BD.PINNUM LEFT JOIN OrderInfo OI ON OI.DOCNUM = BD.DOCNUM AND OI.DOCLIN= BD.DOCLIN LEFT JOIN ShippingInfo S ON S.SRCDOC = OI.PORDOCNUM AND S.SRCLIN = OI.PORLIN LEFT JOIN PBOLH PBH ON PBH.DOCNUM = S.PBHNUM LEFT JOIN ReceiveInfo RI ON RI.SRCDOC = OI.PORDOCNUM AND RI.SRCLIN = OI.PORLIN ORDER BY BD.DOCNUM DESC, BD.DOCLIN;
